from decimal import Decimal


class TwoSlotDailyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily, Market.USA, False
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma_period = 20
        self.spy_closes = deque(maxlen=self.sma_period + 1)

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_last_close = None
        self.aapl_red_streak = 0
        self.aapl_observations = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        self._refresh_lots()

        if data.Bars is None:
            return

        bars = {}
        for symbol in self.symbols.values():
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]
                if not bar.IsFillForward:
                    bars[symbol] = bar

        if self.spy in bars:
            self.spy_closes.append(bars[self.spy].Close)

        if self.aapl in bars:
            close = bars[self.aapl].Close

            if self.aapl_last_close is not None and close < self.aapl_last_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_last_close = close
            self.aapl_observations += 1
            self.aapl_rsi.Update(bars[self.aapl].EndTime, close)

        if len(bars) != len(self.symbols):
            return

        if not self._ready_to_trade():
            return

        crosses_above, crosses_below = self._spy_crosses()
        rsi_above_60 = self.aapl_rsi.Current.Value > Decimal("60")

        if self.strategy_a_lot > 0 and crosses_below:
            self._place_a_order(-self.strategy_a_lot)

        if self.strategy_b_lot > 0 and rsi_above_60:
            self._place_b_order(-self.strategy_b_lot)

        if self.strategy_a_lot == 0 and crosses_above:
            price = bars[self.spy].Close
            quantity = int(
                (self.Portfolio.TotalPortfolioValue * Decimal("0.40")) / price
            )
            if quantity > 0:
                self._place_a_order(quantity)

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = Decimal("20000")
            price = bars[self.aapl].Close

            if self.Portfolio.Cash >= cash_to_invest:
                quantity = int(cash_to_invest / price)
                if quantity > 0:
                    self._place_b_order(quantity)

    def _ready_to_trade(self):
        return (
            len(self.spy_closes) == self.sma_period + 1
            and self.aapl_observations >= 4
            and self.aapl_rsi.IsReady
        )

    def _spy_crosses(self):
        closes = list(self.spy_closes)

        yesterday_close = closes[-2]
        today_close = closes[-1]

        yesterday_sma = sum(closes[:-1]) / self.sma_period
        today_sma = sum(closes[1:]) / self.sma_period

        crosses_above = yesterday_close <= yesterday_sma and today_close > today_sma
        crosses_below = yesterday_close >= yesterday_sma and today_close < today_sma

        return crosses_above, crosses_below

    def _refresh_lots(self):
        self.strategy_a_lot = max(0, int(self.Portfolio[self.spy].Quantity))
        self.strategy_b_lot = max(0, int(self.Portfolio[self.aapl].Quantity))

    def _place_a_order(self, quantity):
        ticket = self.MarketOrder(self.spy, quantity)
        self.strategy_a_lot = max(
            0, self.strategy_a_lot + int(ticket.QuantityFilled)
        )

    def _place_b_order(self, quantity):
        ticket = self.MarketOrder(self.aapl, quantity)
        self.strategy_b_lot = max(
            0, self.strategy_b_lot + int(ticket.QuantityFilled)
        )
