from AlgorithmImports import *
from collections import deque


class TwoSlotDailyStrategy(QCAlgorithm):
    SMA_PERIOD = 50
    RSI_PERIOD = 14
    A_PORTFOLIO_FRACTION = 0.40
    B_CASH_AMOUNT = 20000.0

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self._symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self._symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily, Market.USA, False
            ).Symbol

        self._spy = self._symbols["SPY"]
        self._aapl = self._symbols["AAPL"]

        self._spy_sma = SimpleMovingAverage("SPY_SMA", self.SMA_PERIOD)
        self._aapl_rsi = RelativeStrengthIndex(
            "AAPL_RSI_14", self.RSI_PERIOD, MovingAverageType.Wilders
        )

        self._spy_closes = deque(maxlen=2)
        self._spy_sma_values = deque(maxlen=2)
        self._last_spy_bar_time = None

        self._aapl_previous_close = None
        self._aapl_red_streak = 0
        self._aapl_observations = 0
        self._last_aapl_bar_time = None

        self._a_lot_shares = 0
        self._b_lot_shares = 0

        self._a_buy_pending = False
        self._a_sell_pending = False
        self._b_buy_pending = False
        self._b_sell_pending = False

        self._order_roles = {}

    def OnData(self, data):
        self._update_market_state(data)

        if not self._has_all_real_bars(data):
            return

        if not self._rules_ready():
            return

        sold_a = self._try_sell_a()
        sold_b = self._try_sell_b()

        if not sold_a:
            self._try_buy_a()

        if not sold_b:
            self._try_buy_b()

    def OnOrderEvent(self, order_event):
        role = self._order_roles.get(order_event.OrderId)

        if role is None:
            order = self.Transactions.GetOrderById(order_event.OrderId)
            if order is not None:
                role = order.Tag

        if role not in ("A_BUY", "A_SELL", "B_BUY", "B_SELL"):
            return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            fill_quantity = int(order_event.FillQuantity)

            if role in ("A_BUY", "A_SELL"):
                self._a_lot_shares = max(0, self._a_lot_shares + fill_quantity)
            else:
                self._b_lot_shares = max(0, self._b_lot_shares + fill_quantity)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            self._set_pending(role, False)
            self._order_roles.pop(order_event.OrderId, None)

    def _update_market_state(self, data):
        spy_bar = self._real_bar(data, self._spy)
        if spy_bar is not None and spy_bar.EndTime != self._last_spy_bar_time:
            self._last_spy_bar_time = spy_bar.EndTime
            self._spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            self._spy_closes.append(spy_bar.Close)

            if self._spy_sma.IsReady:
                self._spy_sma_values.append(self._spy_sma.Current.Value)

        aapl_bar = self._real_bar(data, self._aapl)
        if aapl_bar is not None and aapl_bar.EndTime != self._last_aapl_bar_time:
            self._last_aapl_bar_time = aapl_bar.EndTime
            self._aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

            if self._aapl_previous_close is None:
                self._aapl_red_streak = 0
            elif aapl_bar.Close < self._aapl_previous_close:
                self._aapl_red_streak += 1
            else:
                self._aapl_red_streak = 0

            self._aapl_previous_close = aapl_bar.Close
            self._aapl_observations += 1

    def _has_all_real_bars(self, data):
        for symbol in self._symbols.values():
            if self._real_bar(data, symbol) is None:
                return False
        return True

    def _real_bar(self, data, symbol):
        if not data.Bars.ContainsKey(symbol):
            return None

        bar = data.Bars[symbol]
        if bar is None or bar.IsFillForward:
            return None

        return bar

    def _rules_ready(self):
        return (
            self._spy_sma.IsReady
            and len(self._spy_closes) == 2
            and len(self._spy_sma_values) == 2
            and self._aapl_rsi.IsReady
            and self._aapl_observations >= self.RSI_PERIOD + 1
            and self._aapl_observations >= 4
        )

    def _spy_crosses_above_sma(self):
        return (
            self._spy_closes[0] <= self._spy_sma_values[0]
            and self._spy_closes[1] > self._spy_sma_values[1]
        )

    def _spy_crosses_below_sma(self):
        return (
            self._spy_closes[0] >= self._spy_sma_values[0]
            and self._spy_closes[1] < self._spy_sma_values[1]
        )

    def _try_sell_a(self):
        if (
            self._a_lot_shares <= 0
            or self._a_buy_pending
            or self._a_sell_pending
        ):
            return False

        if not self._spy_crosses_below_sma():
            return False

        self._submit_order("A_SELL", self._spy, -self._a_lot_shares)
        return True

    def _try_sell_b(self):
        if (
            self._b_lot_shares <= 0
            or self._b_buy_pending
            or self._b_sell_pending
        ):
            return False

        if float(self._aapl_rsi.Current.Value) <= 60.0:
            return False

        self._submit_order("B_SELL", self._aapl, -self._b_lot_shares)
        return True

    def _try_buy_a(self):
        if (
            self._a_lot_shares > 0
            or self._a_buy_pending
            or self._a_sell_pending
        ):
            return

        if not self._spy_crosses_above_sma():
            return

        close = float(self._spy_closes[-1])
        quantity = int(
            float(self.Portfolio.TotalPortfolioValue)
            * self.A_PORTFOLIO_FRACTION
            / close
        )

        if quantity > 0:
            self._submit_order("A_BUY", self._spy, quantity)

    def _try_buy_b(self):
        if (
            self._b_lot_shares > 0
            or self._b_buy_pending
            or self._b_sell_pending
        ):
            return

        if self._aapl_red_streak < 3:
            return

        if float(self.Portfolio.Cash) < self.B_CASH_AMOUNT:
            return

        close = float(self._aapl_previous_close)
        quantity = int(self.B_CASH_AMOUNT / close)

        if quantity > 0:
            self._submit_order("B_BUY", self._aapl, quantity)

    def _submit_order(self, role, symbol, quantity):
        self._set_pending(role, True)

        try:
            ticket = self.MarketOrder(symbol, quantity, False, role)
        except Exception:
            self._set_pending(role, False)
            raise

        self._order_roles[ticket.OrderId] = role

        if ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            self._set_pending(role, False)

    def _set_pending(self, role, value):
        if role == "A_BUY":
            self._a_buy_pending = value
        elif role == "A_SELL":
            self._a_sell_pending = value
        elif role == "B_BUY":
            self._b_buy_pending = value
        elif role == "B_SELL":
            self._b_sell_pending = value
